const input = $input.first().json;
const required = ['tenantId','providerPhoneNumberId','providerMessageId','mediaId','traceId'];
const missing = required.filter((k) => input[k] === undefined || input[k] === null || input[k] === '');
if (missing.length) throw new Error(`KAPSO_MEDIA_INVALID_INPUT missing=${missing.join(',')}`);
const maxBytes = Number(input.maxBytes ?? 10485760);
if (!Number.isFinite(maxBytes) || maxBytes <= 0) throw new Error('KAPSO_MEDIA_INVALID_MAX_BYTES');
return [{ json: {
  tenantId: String(input.tenantId),
  provider: 'kapso',
  providerPhoneNumberId: String(input.providerPhoneNumberId),
  providerMessageId: String(input.providerMessageId),
  mediaId: String(input.mediaId),
  expectedMediaType: input.expectedMediaType ? String(input.expectedMediaType) : null,
  traceId: String(input.traceId),
  maxBytes,
  idempotencyKey: input.idempotencyKey ? String(input.idempotencyKey) : `kapso-media:${String(input.providerPhoneNumberId)}:${String(input.mediaId)}`
} }];

const request = $('Validate Media Request').first().json;
const metadata = $input.first().json;
if (!metadata || !metadata.id || !metadata.download_url) throw new Error('KAPSO_MEDIA_METADATA_INCOMPLETE');
if (String(metadata.id) !== request.mediaId) throw new Error('KAPSO_MEDIA_ID_MISMATCH');
const sizeBytes = Number(metadata.file_size);
if (!Number.isFinite(sizeBytes) || sizeBytes < 0) throw new Error('KAPSO_MEDIA_SIZE_INVALID');
if (sizeBytes > request.maxBytes) throw new Error(`KAPSO_MEDIA_TOO_LARGE size=${sizeBytes} max=${request.maxBytes}`);
let url;
try { url = new URL(String(metadata.download_url)); } catch { throw new Error('KAPSO_MEDIA_DOWNLOAD_URL_INVALID'); }
if (url.protocol !== 'https:' || url.hostname !== 'api.kapso.ai' || !url.pathname.startsWith('/meta/whatsapp/media_download')) {
  throw new Error('KAPSO_MEDIA_DOWNLOAD_URL_NOT_ALLOWED');
}
return [{ json: {
  ...request,
  mimeType: metadata.mime_type ? String(metadata.mime_type) : 'application/octet-stream',
  sizeBytes,
  providerSha256: metadata.sha256 ? String(metadata.sha256).toLowerCase() : null,
  downloadUrl: String(metadata.download_url),
  downloadUrlExpiresAt: metadata.download_url_expires_at ? String(metadata.download_url_expires_at) : null
} }];

const meta = $('Validate Kapso Media Metadata').first().json;
const current = $input.first();
const localHash = String(current.json.sha256Local ?? current.json.data ?? '').toLowerCase();
if (!localHash) throw new Error('KAPSO_MEDIA_LOCAL_HASH_MISSING');
if (meta.providerSha256 && localHash !== String(meta.providerSha256).toLowerCase()) throw new Error('KAPSO_MEDIA_HASH_MISMATCH');
return [{
  json: {
    schemaVersion: '1.0',
    tenantId: meta.tenantId,
    provider: 'kapso',
    providerPhoneNumberId: meta.providerPhoneNumberId,
    providerMessageId: meta.providerMessageId,
    mediaId: meta.mediaId,
    mimeType: meta.mimeType,
    sizeBytes: meta.sizeBytes,
    sha256: localHash,
    traceId: meta.traceId,
    idempotencyKey: meta.idempotencyKey
  },
  binary: current.binary
}];
